"use strict";function submitForm(n){$("#IsExportExcel").val(n)}function query(n){$.ajax({url:_global.root+"Promotion/GetPromotions",dataType:"html",method:"POST",data:{FromDate:$("#FromDate").val(),ToDate:$("#ToDate").val(),EmpId:$("#EmployeeId").val(),TeamId:$("#TeamId").val()},beforeSend:function(){n||$(".loading-process").fadeIn(300)},success:function(n){$("#list-promotion").html(n);floatThead("table#data")},error:function(){alert(_messages.errorTryAgain)},complete:function(){n||$(".loading-process").fadeOut(300)}})}function deletePromotion(n){confirm("Are you sure you want to delete this promotion?",function(){$.post(_global.root+"Promotion/Delete",{id:n},function(t){t.IsSuccessful?($("#row"+n).remove(),autoIndex()):alert(t.Message)})})}$(document).ready(function(){initAutocomplete("#Employee","#EmployeeId",!1);$("form").submit(function(){var n=$("#Employee").val();return n.length===0&&$("#EmployeeId").val(-1),!0})});$(document).ready(function(){$("#submit").on("click",function(){query(!1)});query(!0)});